import java.util.Properties

plugins {
    id("com.android.application")
    id("kotlin-android")
    id("dev.flutter.flutter-gradle-plugin")
}

// Release signing is mandatory for release builds. The upload key is read from
// android/key.properties (local dev) or generated by CI from repository
// secrets. If the file is absent a release build fails loudly: it must never
// silently fall back to the debug signing key.
val keystoreProperties = Properties()
val keystorePropertiesFile = rootProject.file("key.properties")
val hasKeystoreProperties = keystorePropertiesFile.exists()
if (hasKeystoreProperties) {
    keystorePropertiesFile.inputStream().use { keystoreProperties.load(it) }
}

// Only release-flavoured invocations must hard-fail on a missing key; debug
// builds (which never use the release key) stay buildable for contributors.
val buildingRelease = gradle.startParameter.taskNames.any {
    it.contains("release", ignoreCase = true)
}

android {
    namespace = "com.nexus.comm"
    compileSdk = flutter.compileSdkVersion
    ndkVersion = "28.2.13676358"

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    kotlinOptions {
        jvmTarget = JavaVersion.VERSION_17.toString()
    }

    defaultConfig {
        applicationId = "com.nexus.comm"
        minSdk = 24
        targetSdk = flutter.targetSdkVersion
        versionCode = flutter.versionCode
        versionName = flutter.versionName
    }

    signingConfigs {
        create("release") {
            if (hasKeystoreProperties) {
                storeFile = file(
                    keystoreProperties.getProperty("storeFile")
                        ?: throw GradleException("key.properties is missing 'storeFile'."),
                )
                storePassword = keystoreProperties.getProperty("storePassword")
                    ?: throw GradleException("key.properties is missing 'storePassword'.")
                keyAlias = keystoreProperties.getProperty("keyAlias")
                    ?: throw GradleException("key.properties is missing 'keyAlias'.")
                keyPassword = keystoreProperties.getProperty("keyPassword")
                    ?: throw GradleException("key.properties is missing 'keyPassword'.")
            }
        }
    }

    buildTypes {
        release {
            if (!hasKeystoreProperties && buildingRelease) {
                throw GradleException(
                    "Release signing is not configured: mobile/android/key.properties was not " +
                        "found. Create it from key.properties.example, or let CI generate it from " +
                        "the KEYSTORE_BASE64 / KEY_ALIAS / KEY_PASSWORD / STORE_PASSWORD secrets. " +
                        "Refusing to build a release APK with the debug signing key.",
                )
            }
            signingConfig = if (hasKeystoreProperties) {
                signingConfigs.getByName("release")
            } else {
                null
            }
            isMinifyEnabled = false
            isShrinkResources = false
        }
    }
}

flutter {
    source = "../.."
}
